              "content": "\nimport json\nimport re\nimport pyreadstat\nimport pandas as pd\n\ndef generate_codebook(survey_id, shared_folder, surveys_dir):\n    codebook = {\n        \"survey_id\": survey_id,\n        \"variables\": {}\n    }\n\n    # 1. Load DTA metadata\n    dta_file = f\"{shared_folder}/Quebec Election Study 2018.dta\"\n    df, meta = pyreadstat.read_dta(dta_file)\n    \n    # Create a mapping from variable name to column label from DTA\n    dta_column_labels = dict(zip(meta.column_names, meta.column_labels))\n    dta_variable_value_labels = meta.variable_value_labels\n\n    # 2. Load Markdown content\n    md_file = f\"{surveys_dir}/Quebec Election Study 2018 FR.md\"\n    try:\n        with open(md_file, 'r', encoding='utf-8') as f:\n            md_content = f.read()\n    except FileNotFoundError:\n        print(f\"Error: Markdown file not found at {md_file}\")\n        return\n\n    # BROADER Regular expression to find variable blocks\n    # Looks for a pattern like \"VARNAME: Question text\" or \"VARNAME Question text\"\n    # and captures the block until the next similar pattern or end of file\n    variable_pattern = re.compile(r'^\\\\s*([A-Z_a-z0-9]+):\\\\s*(.*?)(?=\\\\n^\\\\s*[A-Z_a-z0-9]+:|$)', re.MULTILINE | re.DOTALL)\n    \n    markdown_variables = {}\n    for match in variable_pattern.finditer(md_content):\n        var_name = match.group(1).strip()\n        block_content = match.group(0).strip() # Get the entire matched block\n        markdown_variables[var_name] = block_content\n    \n    # Debugging: Print a few found markdown variables\n    print(\"\\n--- Markdown Variables Found (Debug) ---\")\n    for i, (k, v) in enumerate(markdown_variables.items()):\n        if i < 5: # Print first 5 for brevity\n            print(f\"Var: {k}\\nContent:\\n{v[:200]}...\\n\") # Truncate content\n        \n    print(\"----------------------------------------\\n\")\n\n    # Track sources of labels\n    labels_from_sav_only = 0\n    labels_enriched_from_pdf = 0\n    labels_still_null = 0\n    total_variables_with_labels_from_md = 0\n\n    # 3. Iterate through variables from DTA\n    for var_name in meta.column_names:\n        variable_entry = {\n            \"question\": None,\n            \"type\": None,\n            \"values\": {},\n            \"missing\": []\n        }\n\n        # Determine question text\n        dta_question_text = dta_column_labels.get(var_name)\n        if dta_question_text and dta_question_text != var_name:\n            variable_entry[\"question\"] = dta_question_text\n        \n        # Try to find question from markdown if not found in DTA or if it's just the var_name\n        if not variable_entry[\"question\"] or variable_entry[\"question\"] == var_name:\n            if var_name in markdown_variables:\n                block = markdown_variables[var_name]\n                # More precise regex for question within a block\n                question_match = re.search(r'^\\\\s*' + re.escape(var_name) + r':\\\\s*(.*?)(?=\\\\n\\\\s*[-*+]\\\\s*|\\\\n\\\\s*\\\\d+\\\\.\\\\s*|\\\\n\\\\n|Poser|\\\\[|\\\\Z)', block, re.MULTILINE | re.DOTALL)\n                if question_match:\n                    variable_entry[\"question\"] = question_match.group(1).strip()\n\n        # Determine value labels\n        sav_labels = dta_variable_value_labels.get(var_name, {})\n        if sav_labels:\n            variable_entry[\"values\"] = {str(k): v for k, v in sav_labels.items()}\n            labels_from_sav_only += 1\n        elif var_name in markdown_variables:\n            # Search markdown for labels\n            block = markdown_variables[var_name]\n            \n            # Pattern for labels in markdown: e.g., - Masculin, - Féminin, or 1. Oui, 2. Non\n            # We'll try to be flexible with numbered lists and bullet points\n            label_matches = re.findall(r'(?:^\\\\s*[-*+]\\\\s*|\\\\n\\\\s*\\\\d+\\\\.\\\\s*)(.*?)(?=\\\\n(?:\\\\s*[-*+]\\\\s*|\\\\s*\\\\d+\\\\.\\\\s*)|\\\\n\\\\n|\\\\Z)', block, re.MULTILINE)\n            \n            # Special case for QAGE and QAGE2 where labels are descriptive, not code-label pairs\n            if var_name in [\"QAGE\", \"QAGE2\"]:\n                variable_entry[\"values\"] = {} # No explicit code-label pairs\n                # Type will be inferred later, or set to continuous if it contains non-categorical info\n                \n            elif label_matches:\n                extracted_labels = {}\n                # Try to assign sequential numbers as keys if no explicit codes are present\n                current_code = 1\n                for label_line in label_matches:\n                    # Extract explicit code if available (e.g., \"1. Oui\")\n                    code_match = re.match(r'^\\\\s*(\\\\d+)\\\\.\\\\s*(.*)', label_line)\n                    if code_match:\n                        code = code_match.group(1)\n                        label_text = code_match.group(2).strip()\n                    else:\n                        code = str(current_code)\n                        label_text = label_line.strip()\n                        current_code += 1\n                    \n                    # Clean up label text\n                    if label_text and label_text != \"Je préfère ne pas répondre\" and not label_text.startswith(\"- Entrez\"):\n                        extracted_labels[code] = label_text\n                \n                if extracted_labels:\n                    if sav_labels: # if we had SAV labels, this is enrichment\n                        # Merge markdown labels into SAV labels, preferring SAV if conflict\n                        for k, v in extracted_labels.items():\n                            if k not in variable_entry[\"values\"]:\n                                variable_entry[\"values\"][k] = v\n                        labels_enriched_from_pdf += 1\n                    else: # if no SAV labels, markdown is the primary source\n                        variable_entry[\"values\"] = extracted_labels\n                        total_variables_with_labels_from_md += 1\n        \n        # If no labels found at all, try to infer type and keep values empty or populate with nulls\n        if not variable_entry[\"values\"]:\n            # Check if the column exists in the DataFrame to infer type\n            if var_name in df.columns:\n                column_data = df[var_name]\n                unique_values = column_data.nunique()\n\n                if pd.api.types.is_numeric_dtype(column_data):\n                    if unique_values <= 25 and unique_values > 0: # Heuristic for categorical\n                        variable_entry[\"type\"] = \"categorical\"\n                        for val in column_data.unique():\n                            if not pd.isna(val):\n                                variable_entry[\"values\"][str(int(val))] = None\n                        if variable_entry[\"values\"]:\n                            labels_still_null += 1\n                    else:\n                        variable_entry[\"type\"] = \"continuous\"\n                elif pd.api.types.is_string_dtype(column_data):\n                    variable_entry[\"type\"] = \"text\"\n                    if unique_values <= 25 and unique_values > 0: # If text but few unique values, could be categorical\n                        variable_entry[\"type\"] = \"categorical\"\n                        for val in column_data.unique():\n                            if not pd.isna(val):\n                                variable_entry[\"values\"][str(val)] = None\n                        if variable_entry[\"values\"]:\n                            labels_still_null += 1\n            else: # If not in DTA, default to text or categorical empty\n                # This case might happen for variables that are only in markdown but not in the DTA\n                # Or variables for which we just couldn't get info. Default to text.\n                variable_entry[\"type\"] = \"text\"\n\n        else: # If values were found, it's categorical\n            variable_entry[\"type\"] = \"categorical\"\n\n        # Filter out variables with no question text (as per rule)\n        # A variable must have a question to be included. Empty labels are allowed if type is categorical\n        if variable_entry[\"question\"]:\n            codebook[\"variables\"][var_name] = variable_entry\n\n    # Post-processing for reporting\n    total_variables = len(codebook[\"variables\"])\n    \n    # Recalculate labels_still_null based on the final codebook\n    final_null_labels_count = 0\n    for var_data in codebook[\"variables\"].values():\n        if var_data[\"type\"] == \"categorical\" and var_data[\"values\"] and all(v is None for v in var_data[\"values\"].values()):\n            final_null_labels_count += 1\n\n    # Reporting (will be printed by the agent after the script runs)\n    print(f\"Total variables processed: {total_variables}\")\n    print(f\"Labels from SAV only: {labels_from_sav_only}\")\n    print(f\"Labels enriched from PDF/DOC: {labels_enriched_from_pdf}\")\n    print(f\"Labels still null (not found anywhere, populated with nulls from data): {final_null_labels_count}\")\n    print(f\"Total variables with labels primarily from Markdown: {total_variables_with_labels_from_md}\")\n\n    output_path = f\"{surveys_dir}/codebook.json\"\n    with open(output_path, 'w', encoding='utf-8') as f:\n        json.dump(codebook, f, ensure_ascii=False, indent=2)\n\n    print(f\"codebook.json written: {output_path}\")\n\nif __name__ == \"__main__\":\n    import os\n    survey_id = os.environ.get(\"SURVEY_ID\", \"eeq_2018\")\n    shared_folder = os.environ.get(\"SHARED_FOLDER\", \"/home/hubcad25/opubliq/gdrive/_SharedFolder_data_produit/eeq_2018\")\n    surveys_dir = os.environ.get(\"SURVEYS_DIR\", \"/home/hubcad25/opubliq/repos/survey-cleaner/surveys/eeq_2018\")\n    generate_codebook(survey_id, shared_folder, surveys_dir)\n"
